package com.aaliyun.leadnews.article.web;import com.aaliyun.leadnews.article.service.ArticleApplicationService;import com.aaliyun.leadnews.common.api.ResponseResult;import com.aaliyun.leadnews.model.foundation.*;import jakarta.validation.constraints.*;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;import java.util.*;
@RestController @RequestMapping("/api/article") public class ArticleController {private final ArticleApplicationService service;public ArticleController(ArticleApplicationService s){service=s;}@GetMapping("/channels")public ResponseResult<List<ChannelDTO>>channels(){return ResponseResult.success(service.enabledChannels());}@GetMapping("/{id}")public ResponseResult<ArticleApplicationService.ArticleView>detail(@PathVariable Long id){return ResponseResult.success(service.detail(id));}@GetMapping public ResponseResult<PageResponse<ArticleApplicationService.ArticleView>>list(@RequestParam(required=false)Long channelId,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)LocalDateTime publishTime,@RequestParam(defaultValue="1")@Min(1)long page,@RequestParam(defaultValue="10")@Min(1)@Max(100)long size){return ResponseResult.success(service.list(channelId,publishTime,page,size));}}
